SELECT COUNT(*)
FROM   TRIP_STAT
WHERE  TRIP_ID = #{tripId, jdbcType=VARCHAR}

mapper.update:
UPDATE TRIP_STAT SET CATEGORY_STATS = ( SELECT TO_JSONB(JSON_AGG(JSON_BUILD_OBJECT( 'category', category, 'ratio', ratio ))) FROM ( SELECT category, ROUND(cnt * 100.0 / SUM(cnt) OVER(), 0) as ratio FROM ( SELECT COALESCE(A.CATEGORY, 'ETC') as category, COUNT(*) as cnt FROM TRIP_SCHEDULE TS LEFT JOIN BOOKMARK B ON TS.BOOKMARK_ID = B.BOOKMARK_ID LEFT JOIN AREA A ON B.AREA_ID = A.AREA_ID WHERE TS.TRIP_DAY_ID IN ( SELECT TRIP_DAY_ID FROM TRIP_DAY WHERE TRIP_ID = #{tripId} ) GROUP BY COALESCE(A.CATEGORY, 'ETC') ) CATEGORY_CNT ) CATEGORY_RATIO ), REGION_STATS = ( SELECT TO_JSONB(JSON_AGG(JSON_BUILD_OBJECT( 'region', ZDO_NAME, 'ratio', ratio ))) FROM ( SELECT ZDO_NAME, ROUND(cnt * 100.0 / SUM(cnt) OVER(), 0) as ratio FROM ( SELECT R2.ZDO_NAME as ZDO_NAME, COUNT(*) as cnt FROM TRIP_SCHEDULE TS JOIN BOOKMARK B ON TS.BOOKMARK_ID = B.BOOKMARK_ID JOIN AREA A ON B.AREA_ID = A.AREA_ID JOIN REGION R2 ON A.REGION_ID = R2.REGION_ID WHERE TS.TRIP_DAY_ID IN ( SELECT TRIP_DAY_ID FROM TRIP_DAY WHERE TRIP_ID = #{tripId} ) GROUP BY R2.ZDO_NAME
UNION ALL
SELECT R3.ZDO_NAME as ZDO_NAME, 1 as cnt FROM REGION R3 WHERE R3.REGION_ID = (SELECT REGION_ID FROM TRIP WHERE TRIP_ID = #{tripId}) AND NOT EXISTS ( SELECT 1 FROM TRIP_SCHEDULE TS JOIN BOOKMARK B ON TS.BOOKMARK_ID = B.BOOKMARK_ID WHERE TS.TRIP_DAY_ID IN ( SELECT TRIP_DAY_ID FROM TRIP_DAY WHERE TRIP_ID = #{tripId} ) ) ) REGION_CNT ) REGION_RATIO ), UPDATED_AT = NOW() WHERE TRIP_ID = #{tripId, jdbcType=VARCHAR}
